import org.junit.Rule;
import org.junit.rules.TestName;
import java.util.ArrayList;

public class MyClass {
    @Rule
    public TestName testName = new TestName(); // Field declaration

    public void myMethod() {
        int x = 0; // Local variable declaration
        String s = "hello"; // Local variable declaration
        java.util.List<String> list = new ArrayList<>(); // Local variable declaration
    }
}

